sys_script_include.script:
var ResubmitRITMUtils = Class.create();
ResubmitRITMUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
    updateRITM: function() {
        var ritmId = this.getParameter('sysparm_ritm_id');
        var requestedFor = this.getParameter('sysparm_requested_for');
        var computerModel = this.getParameter('sysparm_computer_model');
        var notes = this.getParameter('sysparm_notes');

        var ritm = new GlideRecord('sc_req_item');
        if (ritm.get(ritmId)) {
            ritm.variables.requested_for = requestedFor;
            ritm.variables.computer_model = computerModel;
            ritm.variables.notes = notes;
            ritm.update();
            var requestId = ritm.request;
            var req = new GlideRecord('sc_request');
            if (req.get(requestId)) {
                req.state = -99; // 这里填写你要设定的状态值，例如 '1' 表示 Approved，或使用自定义状态值
                req.update();
            }
            return JSON.stringify({
                status: 'ok',
                req_id: req.sys_id + ''
            });
        }
        return JSON.stringify({
            status: 'fail',
            req_id: ''
        });
    },
    type: 'ResubmitRITMUtils'
});
